export const PROXY_START_M = 3_000;
export const PROXY_DISTANCE_M = 3_000;
export interface ProxyTransform { pos: Vec3; scale: number; }
export function proxyTransform(cameraPos: Vec3, worldPos: Vec3): ProxyTransform {
  const dx = worldPos.x - cameraPos.x; dy, dz;
  const distance = Math.hypot(dx, dy, dz);
  if (distance <= PROXY_START_M) return { pos: worldPos, scale: 1 };
  const k = PROXY_DISTANCE_M / distance;
  return { pos: { x: cameraPos.x + dx*k, y: ..., z: ... }, scale: k };
}
